import{z as s,x as i,o as B,c as l,q as A,j as t,D as a,d as n,s as r,S as o}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"衰减治理","description":"","frontmatter":{"title":"衰减治理","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/sl-decay-governance.md","filePath":"quant/sl-decay-governance.md","lastUpdated":1791063341000}'),p={name:"quant/sl-decay-governance.md"};function d(c,E,C,D,u,f){const e=i("Mermaid");return B(),l("div",null,[E[2]||(E[2]=A('<h1 id="衰减治理" tabindex="-1">衰减治理 <a class="header-anchor" href="#衰减治理" aria-label="Permalink to &quot;衰减治理&quot;">​</a></h1><div class="epigraph"><p>异象被写成论文之后，收益平均要缩水一截：可预测性被套利资本消耗，也被「公开」这件事本身消耗。</p><footer>—— 据 McLean 与 Pontiff, Journal of Finance, 2016 整理</footer></div><p><a href="/quant/sl-capacity-governance">上一课</a>把容量变成治理对象，管的是自己吃掉信号的速度；本课管别人吃掉它的速度。衰减的实证与容量账在<a href="/quant/strategy-capacity-decay">策略容量与衰减</a>，监测侧「怎么听」——原假设带预扣预算的顺序检验——在<a href="/quant/live-drift-monitor">实盘漂移监测</a>。本课写衰减进了台账之后的治理：预算怎么立、三档动作怎么触发、确认衰减之后的去向。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>衰减治理最常见的两种死法，是把两种「坏」混为一谈。把回撤当衰减，会在系统性坏年停掉仍然有效的风险溢价；把衰减当回撤，会在信号真死的时候硬扛到预算外。两者都源于同一缺失：<strong>衰减预算不写在批准记录里</strong>。原假设若默认「IC 永远等于回测」，McLean–Pontiff 一类的发表后缩水会让所有公开来源的信号迟早报警，报警失去信息量。第二层缺口在动作侧：穿带之后去留靠临时开会，结论由会议室里的职位分布决定，而不是由判据决定——监测的统计纪律到此断线。</p><p><span class="marginnote">直觉类比：回撤像天气不好——庄稼还在，等季节过去就有收成；衰减像土壤退化——再等也长不出来。区分二者不能靠感觉，要靠上线前就写死的衰减预算带：坏年落在带内是天气，持续穿带才是退化。</span></p>',6)),(B(),t(o,null,{default:a(()=>[r(e,{id:"mermaid-16",class:"mermaid",graph:"flowchart%20TD%0A%20%20BAD%5B%22%E5%AE%9E%E7%9B%98%E8%A1%A8%E7%8E%B0%E5%8F%98%E5%9D%8F%22%5D%20--%3E%20Q1%7B%22%E8%A1%B0%E5%87%8F%E9%A2%84%E7%AE%97%E5%B8%A6%E9%A2%84%E8%AE%A1%E5%88%B0%E4%BA%86%E5%90%97%3F%22%7D%0A%20%20Q1%20--%3E%7C%22%E5%B8%A6%E5%86%85%EF%BC%9A%E5%B1%9E%E4%BA%8E%E6%BA%A2%E4%BB%B7%E6%B3%A2%E5%8A%A8%22%7C%20KEEP%5B%22%E7%BB%B4%E6%8C%81%E4%BB%93%E4%BD%8D%EF%BC%9A%E6%8C%89%E8%8A%82%E5%A5%8F%E5%A4%8D%E5%AE%A1%22%5D%0A%20%20Q1%20--%3E%7C%22%E7%A9%BF%E5%B8%A6%E4%B8%94%E6%8C%81%E7%BB%AD%20k%20%E6%9C%9F%22%7C%20STOP%5B%22%E5%81%9C%E6%9C%BA%E9%89%B4%E5%88%AB%EF%BC%9A%E4%BF%A1%E5%8F%B7%E5%8F%AF%E8%83%BD%E5%B7%B2%E6%AD%BB%22%5D%0A%20%20KEEP%20--%3E%20ERR1%5B%22%E8%AF%AF%E5%88%A4%E6%88%90%E8%A1%B0%E5%87%8F%E7%9A%84%E4%BB%A3%E4%BB%B7%EF%BC%9A%E5%9C%A8%E6%8A%98%E4%BB%B7%E6%9C%80%E6%B7%B1%E5%A4%84%E6%B8%85%E4%BB%93%22%5D%0A%20%20STOP%20--%3E%20ERR2%5B%22%E8%AF%AF%E5%88%A4%E6%88%90%E5%9B%9E%E6%92%A4%E7%9A%84%E4%BB%A3%E4%BB%B7%EF%BC%9A%E7%A1%AC%E6%89%9B%E5%88%B0%E9%A2%84%E7%AE%97%E5%A4%96%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[n(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>台账衰减字段在上线时就定死三样。<strong>预期衰减带</strong>：发表折扣或拥挤折扣后的预期均值，加减冻结期标准误的若干倍，或一条允许随时间缓降的斜坡；斜坡的斜率本身是假设，复审时重新校准。<strong>复审节奏</strong>：月度读数、季度重校，复审次数进 \\(N\\) 的账——允许无限次「再看一眼」，就会在噪声里找到继续持有的理由，这与<a href="/quant/backtest-overfitting">回测过拟合</a>是同一道算术在时间上的重演。<strong>耗尽判据</strong>：预指定统计量穿带且持续 \\(k\\) 期，由<a href="/quant/cusum-mosum">顺序检验</a>给出受控的错误率，看图做不到。</p><p>三档动作与带的位置绑定。带内只记录；带边缘降杠杆，走辅助线的预授权；穿带确认则停机、进研究账户——但停机不等于退役，下一步是死因鉴别：alpha 漂移、执行漂移还是拥挤漂移，<a href="/quant/live-monitoring-handoff">监控闭环</a>已把这条分诊线预写好。可修的改动即新版本重走台阶；确认不可修的，移交退出机制，那是后面专门的一课。</p><p><span class="marginnote">数字实例：假设每次复审有 5% 的概率在噪声里「找到继续持有的理由」，一年 12 次月度复审，至少中招一次的概率约 \\(1-0.95^{12}\\approx 46\\%\\)。把复审次数计进 \\(N\\)、禁止无限次「再看一眼」，压的正是这个数——它与回测里的反复试优是同一道算术。</span></p>',4)),(B(),t(o,null,{default:a(()=>[r(e,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20BAND%7B%22IC%20%E7%9B%B8%E5%AF%B9%E8%A1%B0%E5%87%8F%E5%B8%A6%E7%9A%84%E4%BD%8D%E7%BD%AE%22%7D%20--%3E%7C%E5%B8%A6%E5%86%85%7C%20LOG%5B%22%E5%8F%AA%E8%AE%B0%E5%BD%95%EF%BC%9A%E6%8C%89%E8%8A%82%E5%A5%8F%E5%A4%8D%E5%AE%A1%22%5D%0A%20%20BAND%20--%3E%7C%E5%B8%A6%E8%BE%B9%E7%BC%98%7C%20TRIM%5B%22%E9%99%8D%E6%9D%A0%E6%9D%86%EF%BC%9A%E8%BE%85%E5%8A%A9%E7%BA%BF%E9%A2%84%E6%8E%88%E6%9D%83%22%5D%0A%20%20BAND%20--%3E%7C%E7%A9%BF%E5%B8%A6%E6%8C%81%E7%BB%AD%20k%20%E6%9C%9F%7C%20STOP%5B%22%E5%81%9C%E6%9C%BA%EF%BC%9A%E8%BF%9B%E7%A0%94%E7%A9%B6%E8%B4%A6%E6%88%B7%EF%BC%8CN%20%E7%BB%A7%E7%BB%AD%E7%B4%AF%E8%AE%A1%22%5D%0A%20%20STOP%20--%3E%20DIAG%5B%22%E6%AD%BB%E5%9B%A0%E9%89%B4%E5%88%AB%EF%BC%9Aalpha%E3%80%81%E6%89%A7%E8%A1%8C%E3%80%81%E6%8B%A5%E6%8C%A4%22%5D%0A%20%20DIAG%20--%3E%20FIX%5B%22%E5%8F%AF%E4%BF%AE%EF%BC%9A%E6%94%B9%E5%8A%A8%E5%8D%B3%E6%96%B0%E7%89%88%E6%9C%AC%E9%87%8D%E8%B5%B0%E5%8F%B0%E9%98%B6%22%5D%0A%20%20DIAG%20--%3E%20RETIRE%5B%22%E4%B8%8D%E5%8F%AF%E4%BF%AE%EF%BC%9A%E7%A7%BB%E4%BA%A4%E9%80%80%E5%87%BA%E6%9C%BA%E5%88%B6%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[n(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=A('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>衰减要预扣而不能事后再议，根本原因是顺序检验的错误率只在「原假设含衰减预算」时受控：预算带就是原假设的形状，事后改带等于移动球门。预扣还改变了组织行为——衰减写成数字后，去留之争变成「读数在带内的哪一格」，而不是「谁更相信这个策略」。拥挤与衰减在机制上耦合：别人吃掉信号的过程会先表现在拥挤相关上，所以衰减治理直接读<a href="/quant/sl-capacity-governance">容量课的同一条预算带</a>，但容量课看的是规模该多大，本课看的是信号还剩多少，两线共用读数、分开动作。</p><p><span class="marginnote">McLean–Pontiff 的样本里，异象收益在样本外约缩水 26%，正式发表后缩水更深；衰减预算若按零衰减设，监测迟早全部误报——预算带是原假设，不是乐观预测。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>衰减预算不是自我实现的预言：预算定的缩水率本身是假设，季度重校可能把它调宽也可能调窄，调带本身要留痕并计一次复审。本课的口径只适用于有对手方的 alpha 信号；纯风险溢价类持仓的「衰减」是风险价格随周期波动，不适用同一套停机逻辑，混用会导致在折价最深处清仓溢价。检验细节——统计量选型、带宽计算、\\(k\\) 的选择——不在此重复，见<a href="/quant/live-drift-monitor">漂移监测</a>与<a href="/quant/cusum-mosum">CUSUM/MOSUM</a>。确认衰减后的清仓怎么走，属于退出机制课。</p><p><span class="marginnote">为什么重要：把风险溢价当 alpha 衰减来停机，会在折价最深处清仓——恰是预期收益最高的时候；把 alpha 衰减当风险溢价硬扛，则会在信号死后继续交学费。两套逻辑混用的结果，是两种错误轮着犯，台账里却找不到是哪一条判据出的错。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>衰减预算写进批准记录：预期带、复审节奏、耗尽判据三者缺一不可。</li><li>原假设必须含预扣衰减，顺序检验的错误率才有意义；复审次数计进 \\(N\\)。</li><li>三档动作绑定带的位置：记录、预授权降杠杆、停机鉴别，去留不进会议室。</li><li>停机不等于退役：死因分诊在前，可修即新版本，不可修才移交退出。</li><li>出处：McLean–Pontiff, <em>JF</em>, 2016；顺序检验见 Brown–Durbin–Evans, <em>JRSS-B</em>, 1975 与<a href="/quant/cusum-mosum">CUSUM/MOSUM</a>；衰减与容量的耦合见<a href="/quant/strategy-capacity-decay">策略容量与衰减</a>。</li></ul>',8))])}const F=s(p,[["render",d]]);export{m as __pageData,F as default};
